#!/bin/sh
# Print the project-scoped Codex MCP config (.codex/config.toml) with absolute paths for THIS checkout.
#   tools/print-codex-config.sh > .codex/config.toml
# Override the workbench directory with OPTICS_PROJ (absolute path to optics-langgraph).
set -eu
ROOT=$(cd "$(dirname "$0")/.." && pwd -P)
PROJ=${OPTICS_PROJ:-$ROOT/handover-review/sanitized/optics-mechanical-ai-handoff/optics-langgraph}
PROJ=$(cd "$PROJ" && pwd -P)
cat <<TOML
# Generated by tools/print-codex-config.sh. Absolute paths: Codex is not known to expand \${VAR} or resolve
# relative command paths in this file. Regenerate on another machine. Mirrors .mcp.json.
# optics-evidence is read-only and its tools run without a prompt. optics-runs starts and controls runs
# (and submits decisions), so every tool of it prompts.

[mcp_servers.optics-evidence]
command = "$PROJ/.venv/bin/python"
args = ["-m", "optics_graph.mcp_evidence"]
default_tools_approval_mode = "approve"

[mcp_servers.optics-evidence.env]
OPTICS_MCP_DATA_DIR = "$PROJ/data-mcp"

[mcp_servers.optics-runs]
command = "$PROJ/.venv/bin/python"
args = ["-m", "optics_graph.mcp_runs"]
default_tools_approval_mode = "prompt"

[mcp_servers.optics-runs.env]
OPTICS_MCP_DATA_DIR = "$PROJ/data-mcp"
TOML
